        uint256 poolSetId,
        uint256 from,
        uint256 to
    ) public view withValidPoolSet(poolSetId) returns (address[] memory pools) {
        uint256 spanLength = _poolSets[poolSetId].length();

        if (from > to || to > spanLength || from >= spanLength) {
            revert IndexOutOfBounds(poolSetId);
